({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [oportunidades, setOportunidades] = useState([]);
  const [actividades, setActividades] = useState([]);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const [resOpps, resActs] = await Promise.all([
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_oportunidades')}?ecosistema=${eco}`),
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_actividades')}?ecosistema=${eco}`)
      ]);
      if (resOpps.ok) setOportunidades(resOpps.registros || []);
      if (resActs.ok) setActividades(resActs.registros || []);
      setCargando(false);
    };
    cargar();
  }, []);

  if (cargando) return <UI.Tarjeta><div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto" size={32} color={tema.colorPrimario} /></div></UI.Tarjeta>;

  const abiertas = oportunidades.filter(o => o.estado === 'abierta');
  const ganadas = oportunidades.filter(o => o.estado === 'ganada');
  const montoAbierto = abiertas.reduce((acc, o) => acc + (Number(o.monto) || 0), 0);
  const montoGanado = ganadas.reduce((acc, o) => acc + (Number(o.monto) || 0), 0);

  const hoy = new Date().toISOString().split('T')[0];
  const actsVencidas = actividades.filter(a => a.estado === 'pendiente' && a.fecha_vencimiento < hoy).length;

  const datosGrafico = abiertas.reduce((acc, o) => {
    const etapa = o.etapa_id || 'Sin etapa';
    const existente = acc.find(x => x.etapa === etapa);
    if (existente) existente.monto += (Number(o.monto) || 0);
    else acc.push({ etapa, monto: Number(o.monto) || 0 });
    return acc;
  }, []);

  return (
    <div className="flex flex-col gap-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.2 }}>
          <UI.Tarjeta className="p-4 flex items-center gap-4">
            <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: tema.colorPrimario + '22', color: tema.colorPrimario }}>
              <Iconos.Target size={20} />
            </div>
            <div>
              <p className="text-xs uppercase font-bold opacity-60" style={{ color: tema.texto }}>{MEITI.t('funnel_value', null, 'Valor del Embudo')}</p>
              <p className="text-xl font-mono font-bold" style={{ color: tema.texto }}>${montoAbierto.toLocaleString()}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.2, delay: 0.1 }}>
          <UI.Tarjeta className="p-4 flex items-center gap-4">
            <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: tema.colorSecundario + '22', color: tema.colorSecundario }}>
              <Iconos.Trophy size={20} />
            </div>
            <div>
              <p className="text-xs uppercase font-bold opacity-60" style={{ color: tema.texto }}>{MEITI.t('won_deals', null, 'Ventas Ganadas')}</p>
              <p className="text-xl font-mono font-bold" style={{ color: tema.texto }}>${montoGanado.toLocaleString()}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.2, delay: 0.2 }}>
          <UI.Tarjeta className="p-4 flex items-center gap-4">
            <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: '#ef444422', color: '#ef4444' }}>
              <Iconos.AlarmClock size={20} />
            </div>
            <div>
              <p className="text-xs uppercase font-bold opacity-60" style={{ color: tema.texto }}>{MEITI.t('overdue_acts', null, 'Actividades Vencidas')}</p>
              <p className="text-xl font-mono font-bold" style={{ color: tema.texto }}>{actsVencidas}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
      </div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.3 }}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.ChartColumn size={18} color={tema.colorPrimario} />
            <h3 className="font-bold text-sm uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('pipeline_chart', null, 'Pipeline por Etapa')}</h3>
          </div>
          {datosGrafico.length === 0 ? (
            <UI.EstadoVacio icono="fa-chart-simple" mensaje={MEITI.t('no_data_chart', null, 'No hay oportunidades abiertas para graficar.')} />
          ) : (
            <div className="w-full h-64">
              <Graficos.ResponsiveContainer width="100%" height="100%">
                <Graficos.BarChart data={datosGrafico} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                  <Graficos.CartesianGrid strokeDasharray="3 3" stroke={tema.texto + '22'} vertical={false} />
                  <Graficos.XAxis dataKey="etapa" stroke={tema.texto} fontSize={12} tickLine={false} axisLine={false} />
                  <Graficos.YAxis stroke={tema.texto} fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `$${v}`} />
                  <Graficos.Tooltip cursor={{fill: tema.texto + '11'}} contentStyle={{ backgroundColor: tema.superficie, borderColor: tema.colorPrimario + '33', borderRadius: '8px', color: tema.texto }} />
                  <Graficos.Bar dataKey="monto" fill={tema.colorPrimario} radius={[4, 4, 0, 0]} />
                </Graficos.BarChart>
              </Graficos.ResponsiveContainer>
            </div>
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [oportunidades, setOportunidades] = useState([]);
  const [etapas, setEtapas] = useState([]);
  const [empresas, setEmpresas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const [resOpps, resEtapas, resEmp] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_oportunidades')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_etapas')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_empresas')}?ecosistema=${eco}`)
    ]);
    if (resOpps.ok) setOportunidades(resOpps.registros.filter(o => o.estado === 'abierta'));
    if (resEtapas.ok) setEtapas((resEtapas.registros || []).sort((a, b) => (a.orden || 0) - (b.orden || 0)));
    if (resEmp.ok) setEmpresas(resEmp.registros || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const moverOportunidad = async (opp, nuevaEtapaId) => {
    const url = `/api/boveda/${MEITI.obtenerTabla('crm_oportunidades')}?ecosistema=${eco}`;
    await MEITI.mutar(url, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...opp, etapa_id: nuevaEtapaId })
    }, {
      alLograr: cargar,
      alFallar: setError
    });
  };

  if (cargando) return <UI.Tarjeta><div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto" size={32} color={tema.colorPrimario} /></div></UI.Tarjeta>;
  if (etapas.length === 0) return <UI.Tarjeta><UI.EstadoVacio icono="fa-layer-group" mensaje={MEITI.t('no_stages', null, 'No hay etapas configuradas. Créalas en Catálogos.')} /></UI.Tarjeta>;

  return (
    <div className="flex flex-col gap-4 h-full">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <div className="flex gap-4 overflow-x-auto pb-4 flex-1 items-start">
        {etapas.map((etapa, index) => {
          const oppsEtapa = oportunidades.filter(o => o.etapa_id === etapa.id);
          const totalEtapa = oppsEtapa.reduce((acc, o) => acc + (Number(o.monto) || 0), 0);
          return (
            <div key={etapa.id} className="flex flex-col gap-3 min-w-[280px] w-[280px] shrink-0">
              <div className="px-3 py-2 rounded-lg flex justify-between items-center" style={{ background: (etapa.color || tema.colorPrimario) + '22', borderTop: `3px solid ${etapa.color || tema.colorPrimario}` }}>
                <span className="font-bold text-sm uppercase tracking-wider" style={{ color: tema.texto }}>{etapa.nombre}</span>
                <span className="font-mono text-xs font-bold" style={{ color: tema.texto }}>${totalEtapa.toLocaleString()}</span>
              </div>
              <div className="flex flex-col gap-2">
                <Animacion.AnimatePresence>
                  {oppsEtapa.map(opp => {
                    const empresa = empresas.find(e => e.id === opp.empresa_id);
                    return (
                      <Animacion.motion.div key={opp.id} initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }} transition={{ duration: 0.2 }}>
                        <div className="p-3 rounded-xl shadow-sm border flex flex-col gap-2" style={{ background: tema.superficie, borderColor: tema.texto + '11' }}>
                          <div className="flex justify-between items-start">
                            <span className="font-bold text-sm leading-tight" style={{ color: tema.texto }}>{opp.titulo}</span>
                            <span className="font-mono text-xs font-bold px-1.5 py-0.5 rounded" style={{ background: tema.fondo, color: tema.colorSecundario }}>${Number(opp.monto).toLocaleString()}</span>
                          </div>
                          <div className="flex items-center gap-1 opacity-70">
                            <Iconos.Building2 size={12} color={tema.texto} />
                            <span className="text-xs truncate" style={{ color: tema.texto }}>{empresa ? empresa.nombre : 'Sin empresa'}</span>
                          </div>
                          <div className="flex justify-between items-center mt-2 pt-2 border-t" style={{ borderColor: tema.texto + '11' }}>
                            <button onClick={() => moverOportunidad(opp, etapas[index - 1].id)} disabled={index === 0} className="p-1 rounded hover:bg-black/5 disabled:opacity-20 transition-colors">
                              <Iconos.ChevronLeft size={16} color={tema.texto} />
                            </button>
                            <span className="text-[10px] uppercase font-bold opacity-50" style={{ color: tema.texto }}>{opp.fecha_cierre ? opp.fecha_cierre.substring(5,10) : '--/--'}</span>
                            <button onClick={() => moverOportunidad(opp, etapas[index + 1].id)} disabled={index === etapas.length - 1} className="p-1 rounded hover:bg-black/5 disabled:opacity-20 transition-colors">
                              <Iconos.ChevronRight size={16} color={tema.texto} />
                            </button>
                          </div>
                        </div>
                      </Animacion.motion.div>
                    );
                  })}
                </Animacion.AnimatePresence>
                {oppsEtapa.length === 0 && (
                  <div className="p-4 text-center border border-dashed rounded-xl opacity-40" style={{ borderColor: tema.texto, color: tema.texto }}>
                    <span className="text-xs">{MEITI.t('empty_stage', null, 'Vacío')}</span>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const tOpps = MEITI.obtenerTabla('crm_oportunidades');

  const vacio = { id: '', titulo: '', empresa_id: '', contacto_id: '', monto: '', etapa_id: '', probabilidad: '50', fecha_cierre: '', estado: 'abierta', notas: '' };
  const [form, setForm] = useState(vacio);
  const [oportunidades, setOportunidades] = useState([]);
  const [empresas, setEmpresas] = useState([]);
  const [contactos, setContactos] = useState([]);
  const [etapas, setEtapas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const [resOpps, resEmp, resCont, resEtapas] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${tOpps}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_empresas')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_contactos')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_etapas')}?ecosistema=${eco}`)
    ]);
    if (resOpps.ok) setOportunidades(resOpps.registros || []);
    if (resEmp.ok) setEmpresas(resEmp.registros || []);
    if (resCont.ok) setContactos(resCont.registros || []);
    if (resEtapas.ok) setEtapas((resEtapas.registros || []).sort((a,b) => (a.orden||0)-(b.orden||0)));
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setError(null); setExito(null);
    if (!form.titulo.trim() || !form.etapa_id) return setError(MEITI.t('req_opp_fields', null, 'Título y etapa son obligatorios.'));

    setGuardando(true);
    const payload = {
      id: form.id || 'opp_' + Date.now(),
      usuario_id: uid,
      titulo: form.titulo.trim(),
      empresa_id: form.empresa_id,
      contacto_id: form.contacto_id,
      monto: Number(form.monto) || 0,
      etapa_id: form.etapa_id,
      probabilidad: Number(form.probabilidad) || 0,
      fecha_cierre: form.fecha_cierre,
      estado: form.estado,
      notas: form.notas
    };

    await MEITI.mutar(`/api/boveda/${tOpps}?ecosistema=${eco}`, {
      method: form.id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setExito(MEITI.t('opp_saved', null, 'Oportunidad guardada.')); setForm(vacio); cargar(); setGuardando(false); },
      alFallar: (err) => { setError(err || MEITI.t('err_save', null, 'Error al guardar.')); setGuardando(false); }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('del_opp_q', null, '¿Borrar esta oportunidad?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_del', null, 'Sí, borrar'), tono: 'peligro' })) return;
    await MEITI.mutar(`/api/boveda/${tOpps}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, {
      alLograr: () => { setExito(MEITI.t('opp_deleted', null, 'Oportunidad borrada.')); if (form.id === id) setForm(vacio); cargar(); },
      alFallar: (err) => setError(err || MEITI.t('err_del', null, 'Error al borrar.'))
    });
  };

  const editar = (fila) => {
    setForm({ ...vacio, ...fila, monto: String(fila.monto || ''), probabilidad: String(fila.probabilidad || '') });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const columnas = [
    { clave: 'estado', etiqueta: '', render: (f) => <div className="w-2 h-2 rounded-sm" style={{ background: f.estado === 'ganada' ? '#10b981' : f.estado === 'perdida' ? '#ef4444' : tema.colorPrimario }}></div> },
    { clave: 'titulo', etiqueta: MEITI.t('col_title', null, 'Título') },
    { clave: 'empresa_id', etiqueta: MEITI.t('col_company', null, 'Empresa'), render: (f) => empresas.find(e => e.id === f.empresa_id)?.nombre || '--' },
    { clave: 'etapa_id', etiqueta: MEITI.t('col_stage', null, 'Etapa'), render: (f) => etapas.find(e => e.id === f.etapa_id)?.nombre || '--' },
    { clave: 'fecha_cierre', etiqueta: MEITI.t('col_close_date', null, 'Cierre'), render: (f) => <span className="font-mono text-xs">{f.fecha_cierre ? f.fecha_cierre.substring(5,10) : '--'}</span> },
    { clave: 'monto', etiqueta: MEITI.t('col_amount', null, 'Monto'), render: (f) => <span className="font-mono text-sm">${Number(f.monto).toLocaleString()}</span> }
  ];

  return (
    <div className="flex flex-col gap-4">
      <Animacion.motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.2 }}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.Target size={18} color={tema.colorPrimario} />
            <UI.Etiqueta>{form.id ? MEITI.t('edit_opp', null, 'Editar Oportunidad') : MEITI.t('new_opp', null, 'Nueva Oportunidad')}</UI.Etiqueta>
          </div>
          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />
          <form onSubmit={guardar} className="flex flex-col gap-3">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_title', null, 'Título')} tipo="text" valor={form.titulo} onChange={e => setForm({...form, titulo: e.target.value})} placeholder="Ej: Venta Licencias 2026" /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_amount', null, 'Monto Estimado')} tipo="number" valor={form.monto} onChange={e => setForm({...form, monto: e.target.value})} /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_company', null, 'Empresa')} tipo="select" valor={form.empresa_id} onChange={e => setForm({...form, empresa_id: e.target.value})} opciones={[{value:'', label:'-- Seleccionar --'}, ...empresas.map(e => ({value: e.id, label: e.nombre}))]} /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_contact', null, 'Contacto')} tipo="select" valor={form.contacto_id} onChange={e => setForm({...form, contacto_id: e.target.value})} opciones={[{value:'', label:'-- Seleccionar --'}, ...contactos.filter(c => !form.empresa_id || c.empresa_id === form.empresa_id).map(c => ({value: c.id, label: c.nombre}))]} /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_stage', null, 'Etapa')} tipo="select" valor={form.etapa_id} onChange={e => setForm({...form, etapa_id: e.target.value})} opciones={[{value:'', label:'-- Seleccionar --'}, ...etapas.map(e => ({value: e.id, label: e.nombre}))]} /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_close_date', null, 'Fecha Cierre')} tipo="date" valor={form.fecha_cierre} onChange={e => setForm({...form, fecha_cierre: e.target.value})} /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_status', null, 'Estado')} tipo="select" valor={form.estado} onChange={e => setForm({...form, estado: e.target.value})} opciones={[{value:'abierta', label:'Abierta'}, {value:'ganada', label:'Ganada'}, {value:'perdida', label:'Perdida'}]} /></div>
              <div className="flex-1"><UI.Campo etiqueta={MEITI.t('f_prob', null, 'Probabilidad (%)')} tipo="number" valor={form.probabilidad} onChange={e => setForm({...form, probabilidad: e.target.value})} /></div>
            </div>
            <div className="flex gap-2 mt-2">
              <UI.Boton tipo="submit" variante="primario" disabled={guardando}><Iconos.Save size={16} className="mr-2 inline" />{guardando ? MEITI.t('saving', null, 'Guardando...') : MEITI.t('save', null, 'Guardar')}</UI.Boton>
              {form.id && <UI.Boton tipo="button" variante="secundario" onClick={() => setForm(vacio)}><Iconos.X size={16} className="mr-2 inline" />{MEITI.t('cancel', null, 'Cancelar')}</UI.Boton>}
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <UI.Tarjeta>
        <div className="text-xs uppercase tracking-wider opacity-60 px-4 py-2" style={{ background: tema.texto + '08' }}>
          {MEITI.t('opps_list', null, 'Listado de Oportunidades')} · {oportunidades.length}
        </div>
        {cargando ? <div className="p-4 text-sm" style={{color: tema.texto}}>{MEITI.t('loading', null, 'Cargando...')}</div> : oportunidades.length === 0 ? <UI.EstadoVacio icono="fa-box-open" mensaje={MEITI.t('no_opps', null, 'No hay oportunidades registradas.')} /> : (
          <div className="[&_td]:py-2 [&_th]:py-2">
            <UI.TablaDatos columnas={columnas} datos={oportunidades} claveId="id" onEditar={editar} onBorrar={(f) => borrar(f.id)} />
          </div>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const tCont = MEITI.obtenerTabla('crm_contactos');

  const vacio = { id: '', nombre: '', empresa_id: '', cargo: '', email: '', telefono: '', notas: '' };
  const [form, setForm] = useState(vacio);
  const [contactos, setContactos] = useState([]);
  const [empresas, setEmpresas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const [resCont, resEmp] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${tCont}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('crm_empresas')}?ecosistema=${eco}`)
    ]);
    if (resCont.ok) setContactos(resCont.registros || []);
    if (resEmp.ok) setEmpresas(resEmp.registros || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
